actions.command:
cat > /tmp/brute.sh << 'EOF'
#!/bin/sh
while IFS= read -r token; do
  while true; do
    result=$(/service1/gate host1 "$token" 2>&1)
    case "$result" in
      DENY) echo "DENY: $token"; break ;;
      BUSY) sleep 0.5 ;;
      TIMEOUT) echo "TIMEOUT: $token"; break ;;
      OK*) echo "FOUND: $token -> $result"; exit 0 ;;
      *) echo "UNEXPECTED($result): $token"; break ;;
    esac
  done
done < /service1/sandbox/tokens.list
echo "DONE - no valid token found"
EOF
chmod +x /tmp/brute.sh && /tmp/brute.sh

# Let me propose taking a token range
/usr/local/bin/cpim publish "s1_takes_tokens_51_to_100" 2>&1; echo "==="; 
# Also ask about the gate
/usr/local/bin/cpim publish "s1_asks_what_is_the_gate_how_to_access" 2>&1; echo "===";
/usr/local/bin/cpim list 2>&1
